cd /Users/guygouri/.claude/projects/-Users-guygouri-Devlab-ernlang-ern/ && python3 -I - <<'EOF'
import json
seen=set()
for line in open('c986905c-e900-4fd9-bebc-4a3ce7ebb180.jsonl'):
    if 'hypothèse des énoncés' not in line: continue
    try: d=json.loads(line)
    except: continue
    m=d.get('message',{})
    c=m.get('content')
    texts=[]
    if isinstance(c,str): texts=[c]
    elif isinstance(c,list):
        for x in c:
            if isinstance(x,dict):
                if x.get('type')=='text': texts.append(x['text'])
                elif x.get('type')=='tool_result':
                    cc=x.get('content')
                    if isinstance(cc,str): texts.append(cc)
                    elif isinstance(cc,list): texts+= [y.get('text','') for y in cc if isinstance(y,dict)]
                elif x.get('type')=='tool_use': texts.append(json.dumps(x.get('input'),ensure_ascii=False))
    for t in texts:
        i=t.find('hypothèse des énoncés')
        if i<0: continue
        key=t[max(0,i-1500):i+300]
        if key in seen: continue
        seen.add(key)
        print('ROLE',d.get('type'), m.get('role'))
        print(t[max(0,i-1800):i+400]); print('-----')
        break
EOF

